generation_rounds.planner_raw:
{
  "strategy": "Answer from scratch by locating the frame or short interval where the car's speed/velocity is shown, then read the on-screen text or structured visual directly. Use the smallest chain that can handle either a plain speed label or a graph/diagram if present.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "temporal_grounder",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "query": "scene showing a car's velocity or speed value on screen, such as a speed label, equation, graph, chart, or diagram about the car's motion"
      },
      "purpose": "Localize the most likely interval where the answer-bearing visual about the car's velocity appears before retrieving frames.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "query": null,
        "timestamps": [
          "<STEP_1:segments[0].start>",
          "<STEP_1:segments[0].end>",
          "<STEP_1:segments[1].start>"
        ],
        "num_frames": 3
      },
      "purpose": "Sample candidate frames from top localized intervals to capture the actual question-bearing frame and avoid committing to a possibly partial or wrong-phase visual.",
      "depends_on": [
        1
      ]
    },
    {
      "step": 3,
      "tool": "ocr",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null
      },
      "purpose": "Read visible text, numbers, and units in the candidate frames to see whether the car's velocity is explicitly written on screen.",
      "depends_on": [
        2
      ]
    },
    {
      "step": 4,
      "tool": "chart_analyzer",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null,
        "query": "graph, diagram, or structured visual showing the car's velocity or speed value"
      },
      "purpose": "Interpret the frame if the velocity is conveyed via a graph, chart, or motion diagram rather than plain text alone.",
      "depends_on": [
        2
      ]
    }
  ],
  "refinement_instructions": "Build a first trace from the new evidence only; do not rely on any prior answer or unstated assumptions. First identify which frame-level result from step 2 actually contains the answer-bearing visual by matching the OCR output from step 3 and, if needed, the structured interpretation from step 4. Prefer direct on-screen numeric evidence with units such as m/s. If step 3 clearly reads a single velocity value for the car, cite that OCR evidence directly and map it to the matching option. If the value is shown through a graph/diagram instead of plain text, use step 4 as the authoritative source and cite the exact interpreted value or relationship. Reconcile OCR and chart evidence on the same frame by stable cues like the visible number, axis labels, or the car-specific label. Do not infer from plausibility; if multiple candidate frames disagree, choose the one that explicitly refers to the car's velocity in the question-bearing visual. Update the final answer to the option whose value matches the grounded velocity."
}
